def build_zh_hk():
    """Derive zh-HK from zh-hans with OpenCC s2hk, then apply overrides."""
    import opencc
    cc = opencc.OpenCC("s2hk")
    out = {}
    for k, v in S["zh-hans"].items():
        out[k] = cc.convert(v)
    out.update(ZH_HK_OVERRIDES)
    return out


S["zh-hk"] = build_zh_hk()

